package com.aditya.fefo.controller;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import com.aditya.fefo.dto.AuthDtos.*; import com.aditya.fefo.dto.ProductDtos.*; import com.aditya.fefo.service.*; import com.aditya.fefo.security.JwtService; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest; import org.springframework.boot.test.mock.mockito.MockBean; import org.springframework.http.MediaType; import org.springframework.security.test.context.support.WithMockUser; import org.springframework.test.web.servlet.MockMvc; import java.util.*; import static org.mockito.Mockito.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(controllers={AuthController.class,ProductController.class})
@AutoConfigureMockMvc(addFilters = false) class ControllerTests { @Autowired MockMvc mvc; @MockBean AuthService auth; @MockBean ProductService products; @MockBean JwtService jwtService; @Test void loginReturnsToken()throws Exception{when(auth.login(any())).thenReturn(new LoginResponse("abc","Bearer",3600,new UserDto("1","staff","STAFF")));mvc.perform(post("/api/v1/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"username\":\"staff\",\"password\":\"password\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.accessToken").value("abc"));}@Test @WithMockUser(roles="STAFF") void listProducts()throws Exception{when(products.list()).thenReturn(List.of(new ProductResponse(UUID.randomUUID(),"SKU","Milk","",true)));mvc.perform(get("/api/v1/products")).andExpect(status().isOk()).andExpect(jsonPath("$[0].sku").value("SKU"));}@Test @WithMockUser(roles="STAFF") void productValidation()throws Exception{mvc.perform(post("/api/v1/products").contentType(MediaType.APPLICATION_JSON).content("{\"sku\":\"\",\"name\":\"\"}")).andExpect(status().isBadRequest());}}

